//! Examples generated by the Server's current readers and save path.
use serde_json::{Value, json};

fn fixture() -> Value {
    serde_json::from_str(include_str!(
        "../../../../server/tests/data/composition-rules-server-cases.json"
    ))
    .unwrap()
}
fn call(f: fn(&[u8]) -> Vec<u8>, request: &Value) -> Value {
    serde_json::from_slice(&f(&serde_json::to_vec(request).unwrap())).unwrap()
}

#[test]
fn keeping_kinds_returns_walk_order_and_matches_server_set() {
    use std::collections::BTreeSet;
    let server = include_str!("../../../../server/src/inku_server/persistence/description_lock.py");
    let contents = server
        .split_once("COMPOSITION_KEEPING_KINDS = frozenset({")
        .unwrap()
        .1
        .split_once("})")
        .unwrap()
        .0;
    let server_kinds: BTreeSet<&str> = contents
        .lines()
        .map(str::trim)
        .filter(|line| line.starts_with('"'))
        .map(|line| line.trim_end_matches(',').trim_matches('"'))
        .collect();
    let response = call(
        crate::composition_rules::composition_rules_json,
        &json!({"action": "keeping_kinds"}),
    );
    assert_eq!(
        response,
        json!({"schema":"inku.composition-rules.v1", "outcome":"ok", "result":{"kinds": crate::composition_rules::KEEPING}})
    );
    let core_kinds: BTreeSet<&str> = crate::composition_rules::KEEPING.iter().copied().collect();
    assert_eq!(core_kinds, server_kinds);
}

#[test]
fn boxes_and_ancestry_match_server_examples() {
    let cases = fixture();
    for case in cases["boxes"].as_array().unwrap() {
        let actual = call(crate::chunk_moves::chunk_moves_json, &case["input"]);
        assert_eq!(actual["outcome"], "ok", "{actual}");
        assert_eq!(
            json!({"units": actual["units"], "free_lines": actual["free_lines"]}),
            case["expected"]
        );
    }
    for case in cases["walk"].as_array().unwrap() {
        let actual = call(
            crate::composition_rules::composition_rules_json,
            &case["input"],
        );
        assert_eq!(actual["outcome"], "ok", "{actual}");
        assert_eq!(actual["result"], case["expected"], "{}", case["input"]);
    }
}

#[test]
fn derivation_metadata_matches_server_examples() {
    for case in fixture()["metadata"].as_array().unwrap() {
        let actual = call(
            crate::composition_rules::composition_rules_json,
            &case["input"],
        );
        if let Some(reason) = case["expected"].get("refused") {
            assert_eq!(actual["outcome"], "refused");
            assert_eq!(&actual["reason"], reason);
        } else {
            assert_eq!(actual["outcome"], "ok", "{actual}");
            assert_eq!(actual["result"], case["expected"]);
        }
    }
}

#[test]
fn thesis_retry_and_digest_match_server_and_provider_wire_accepts_the_request() {
    let cases = fixture();
    for case in cases["digest"].as_array().unwrap() {
        let actual = call(
            crate::composition_theses::composition_theses_json,
            &json!({"action":"digest", "request":case["request"]}),
        );
        assert_eq!(actual["prompt_digest"], case["expected"]);
    }
    for case in cases["retry"].as_array().unwrap() {
        let actual = call(
            crate::composition_theses::composition_theses_json,
            &json!({"action":"retry", "ask":case["ask"], "answer":case["answer"], "attempt":1}),
        );
        assert_eq!(actual["next"], "send", "{actual}");
        for key in ["request", "prompt_id", "prompt_digest"] {
            assert_eq!(actual[key], case["expected"][key]);
        }
        let last = call(
            crate::composition_theses::composition_theses_json,
            &json!({"action":"retry", "ask":case["ask"], "answer":case["answer"], "attempt":2}),
        );
        assert_eq!(last["outcome"], "refused");
        let request = &actual["request"];
        let prompt = json!({"system": request["system"], "message": request["text"], "response_schema": request["response_schema"], "action_name":"generate_normalized_ddl"});
        let wire = call(
            crate::provider_wire::provider_wire_json,
            &json!({"action":"pipeline_request", "connection":{"id":"openai", "kind":"openai_compatible", "base_url":"https://api.openai.com/v1"}, "model":"gpt-4o", "max_tokens":request["max_tokens"], "prompt":prompt}),
        );
        assert_eq!(wire["outcome"], "ok", "{wire}");
        let body: Value = serde_json::from_str(wire["body"].as_str().unwrap()).unwrap();
        assert_eq!(body["instructions"], request["system"]);
        assert_eq!(body["input"][0]["content"], request["text"]);
        assert_eq!(
            body["tools"][0]["parameters"]["properties"]["theses"]["type"],
            "array"
        );
    }
}
